returns one outcome record per event.
"""
from .hashing import fold_key
from .settings import load_settings


def live_ring(settings=None):
    """The live shards, in ring order. The tracking page and the reconciliation job read these."""
    if settings is None:
        settings = load_settings()
    return list((settings.get("shards") or {}).get("live") or [])


def bucket_for(reference, ring_size, settings=None):
    """Ring index for a shipment reference, in [0, ring_size)."""
    return int(fold_key(reference) % ring_size)

