"""The routing path: put each scan event on a live shard and record the outcome.

`bucket_for(reference, ring_size, settings=None)` returns the ring index for a shipment reference.
`route_batch(events, sink, settings=None)` writes a batch in order through the injected sink and
returns one outcome record per event.

The ring index is currently taken with a C-truncated modulo, matching how the reference implementation
was written in the producer's language.
"""
import math

from .hashing import fold_key
from .settings import load_settings


def live_ring(settings=None):
    """The live shards, in ring order. The tracking page and the reconciliation job read these."""
    if settings is None:
        settings = load_settings()
    return list((settings.get("shards") or {}).get("live") or [])


def bucket_for(reference, ring_size, settings=None):
    """Ring index for a shipment reference."""
    return int(math.fmod(fold_key(reference), ring_size))


def route_batch(events, sink, settings=None):
    """Write a batch in order. Returns one outcome record per event."""
    if settings is None:
        settings = load_settings()
    ring = live_ring(settings)
    by_bucket = dict(enumerate(ring))
    records = []
    for event in events:
        try:
            shard = by_bucket[bucket_for(event["key"], len(ring), settings)]
        except Exception as exc:
            records.append({"id": event["id"], "outcome": "dropped", "error": type(exc).__name__})
            continue
        sink.write(shard, event)
        records.append({"id": event["id"], "outcome": "stored", "shard": shard})
    return records

